return items.map(item => {
  const email = item.json['EMAIL'] || '';
  if (!email || !email.includes('@')) {
    item.json['Status'] = 'Invalid Email';
    item.json['skip'] = true;
  } else {
    item.json['skip'] = false;
  }
  return item;
});

return items.map(item => {
  const segment = (item.json['Segment'] || '').toLowerCase();
  const activity = (item.json['ACTIVITY'] || '').toLowerCase();
  const fintechKeywords = ['payments', 'fintech', 'payout', 'gateway'];
  const verificationKeywords = ['kyc', 'pan', 'aadhaar', 'gst', 'verification'];

  let mode = 'fintech';
  let products = ['payouts', 'QR', 'bill pay', 'gateway', 'remittance'];

  if (verificationKeywords.some(k => segment.includes(k) || activity.includes(k))) {
    mode = 'verification';
    products = ['PAN', 'Aadhaar', 'GST', 'bank account', 'KYC'];
  }

  item.json['structuredPayload'] = {
    company: item.json['COMPANY NAME'],
    email: item.json['EMAIL'],
    state: item.json['STATE'],
    district: item.json['DISTRICT'],
    activity: item.json['ACTIVITY'],
    segment: item.json['Segment'],
    mode,
    products
  };

  return item;
});

// Robust parser for OpenAI output with subject/body_html/cta_text

function firstStringCandidate(obj) {
  if (!obj) return "";
  const paths = [
    "message.content",
    "choices[0].message.content",
    "text",
    "data",
    "result",
    "output",
    "content"
  ];

  for (const path of paths) {
    try {
      const parts = path.split(".");
      let value = obj;
      for (const part of parts) {
        if (!value) break;
        value = value[part];
      }
      if (typeof value === "string" && value.trim().startsWith("{")) return value;
    } catch (e) {}
  }
  return "";
}

function extractJson(text) {
  try {
    const match = text.match(/{[\s\S]*}/);
    return match ? JSON.parse(match[0]) : null;
  } catch (err) {
    return null;
  }
}

function cleanFences(text) {
  if (!text) return "";
  return text.replace(/```(json)?/gi, "").trim();
}

return items.map(item => {
  const j = item.json;

  // Step 1: Grab raw string output from OpenAI
  const rawCandidate = firstStringCandidate(j);
  const raw = cleanFences(rawCandidate);

  // Step 2: Try to parse
  const obj = extractJson(raw);

  // Step 3: Fallbacks if parsing fails
  const subject = obj?.subject ?? "Couldn’t parse subject";
  const body = obj?.body_html ?? "<p>Couldn’t parse body</p>";
  const cta = obj?.cta_text ?? "Reply Now";

  return {
    json: {
   EMAIL: item.json?.["Prep Row"]?.EMAIL || "",
      parsed_subject: subject,
      parsed_body_html: body,
      parsed_cta_text: cta,
      AI_Raw: raw,
      Status: obj ? "Drafted" : "AI_PARSE_ERROR"
    }
  };
});

