  .replace(/{{SUBJECT}}/g, subject)
  .replace(/{{SUBHEAD}}/g, subhead)
  .replace(/{{AI_BODY_HTML}}/g, aiBody)
  .replace(/{{CTA_TEXT}}/g, ctaText)
  .replace(/{{CTA_URL}}/g, ctaUrl)
  .replace(/{{LOGO_URL}}/g, logoUrl);

return [{
  json: {
    ...$input.first().json,
    final_subject: subject,
    final_html: html
  }
}];
